const followingKey='slice-following-v1';const followedData=readStored(followingKey,[]);let followedAuthors=new Set(Array.isArray(followedData)?followedData.filter(x=>typeof x==='string'):[]);
const followingDialog=document.createElement('dialog');followingDialog.id='following-dialog';followingDialog.setAttribute('aria-labelledby','following-title');document.body.append(followingDialog);
const followingPage=document.createElement('main');followingPage.id='following-page';followingPage.hidden=true;document.querySelector('main#discover').after(followingPage);
function setFollows(next){try{localStorage.setItem(followingKey,JSON.stringify([...next]))}catch{toast('关注未保存，请检查浏览器存储空间');return false}followedAuthors=next;renderFollowingFeed();return true}
function renderFollowing(){const creators=[...new Set(works.map(w=>w.author))];followingDialog.innerHTML=`<div class="dialog-head"><span>YOUR SLICERS</span><button data-close-following aria-label="关闭管理关注">✕</button></div><h2 id="following-title">管理关注</h2><p>关注喜欢的 Slicer，他们的 Slice 会出现在关注 Feed。</p><div class="following-creators">${creators.map((a,i)=>`<article><span class="following-avatar">${escapeHtml(a.slice(0,1))}</span><div><strong>${escapeHtml(a)}</strong><small>${works.filter(w=>w.author===a).length} 个 Slice · ${escapeHtml(works.find(w=>w.author===a).cat)}</small></div><button data-follow-index="${i}" aria-pressed="${followedAuthors.has(a)}">${followedAuthors.has(a)?'已关注 ✓':'＋ 关注'}</button></article>`).join('')}</div>`;followingDialog.querySelectorAll('[data-follow-index]').forEach(b=>b.onclick=()=>{const a=creators[+b.dataset.followIndex],next=new Set(followedAuthors);next.has(a)?next.delete(a):next.add(a);if(setFollows(next))renderFollowing()})}
function renderFollowingFeed(){const list=works.filter(w=>followedAuthors.has(w.author));followingPage.innerHTML=`<div class="following-page-heading"><div><span class="eyebrow">YOUR SLICERS, THEIR SLICES</span><h1>Slicers</h1><p>来自你关注的 Slicer，每一个 Slice 都可以直接探索。</p></div><button data-manage-following>管理关注 <span>${followedAuthors.size}</span></button></div><div class="following-feed-layout"><section class="following-stream" aria-label="关注的 Slice 信息流">${list.length?list.map(w=>`<article class="card following-feed-card"><div class="following-byline"><span class="following-avatar">${escapeHtml(w.author.slice(0,1))}</span><div><strong>${escapeHtml(w.author)}</strong><small>${escapeHtml(w.time)} · ${escapeHtml(w.cat)}</small></div><span>已关注</span></div><h3>${escapeHtml(w.title)}</h3><p>${escapeHtml(w.desc)}</p>${stage(w)}<div class="card-actions"><button data-like="${w.id}" class="${likes.has(w.id)?'liked':''}" aria-pressed="${likes.has(w.id)}" aria-label="喜欢 ${escapeHtml(w.title)}">${likes.has(w.id)?'♥':'♡'} ${w.likes+(likes.has(w.id)?1:0)}</button><button data-share="${w.id}">↗ Share</button><button data-remix="${w.id}">${w.daily?'写同款':'⤨ Remix'}</button><button data-save="${w.id}" aria-pressed="${libraryIds.has(w.id)}">${libraryIds.has(w.id)?'✓ 已收藏':'＋ Library'}</button><button data-open="${w.id}">${w.daily?'读全文':'打开 Slice'} ↗</button></div></article>`).join(''):'<div class="following-feed-empty"><span>✳</span><h2>从关注一个 Slicer 开始。</h2><p>这里将呈现他们发布的 Slice，你可以直接浏览、试玩和收藏。</p><button class="dark" data-manage-following>发现 Slicer →</button><button data-demo-following>体验示例关注 Feed</button></div>'}</section><aside class="following-feed-aside"><h3>你关注的 Slicer</h3>${[...followedAuthors].map(a=>`<div class="followed-person"><span class="following-avatar">${escapeHtml(a.slice(0,1))}</span><span>${escapeHtml(a)}</span></div>`).join('')||'<p>还没有关注的 Slicer。</p>'}<button data-manage-following>发现更多 Slicer ＋</button><p class="following-local-note">当前为原型内容。关注关系保存在本机，跨设备同步尚未接入。</p></aside></div>`;initStages(followingPage)}
function showFollowing(){document.querySelector('main#discover').hidden=true;followingPage.hidden=false;renderFollowingFeed();document.querySelectorAll('header nav a').forEach(a=>{a.classList.toggle('current',a.id==='following-link');if(a.id==='following-link')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function syncFollowingRoute(){if(location.hash==='#following')showFollowing();else{followingPage.hidden=true;document.querySelector('main#discover').hidden=false;document.querySelectorAll('header nav a').forEach(a=>{const current=a.getAttribute('href')===(location.hash==='#trending'?'#trending':'#discover');a.classList.toggle('current',current);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}}
document.querySelector('#following-link').onclick=e=>{e.preventDefault();if(location.hash==='#following')showFollowing();else location.hash='following';window.scrollTo({top:0,behavior:'smooth'})};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-manage-following')){renderFollowing();followingDialog.showModal()}if(b.hasAttribute('data-close-following'))followingDialog.close();if(b.hasAttribute('data-demo-following')){setFollows(new Set([...followedAuthors,'小禾','阿宁的饭桌','Kepler Lab']));toast('已关注 3 位示例 Slicer，可在管理关注中修改')}});
const beforeFollowingRender=render;render=function(){beforeFollowingRender();if(!followingPage.hidden)renderFollowingFeed()};
window.addEventListener('hashchange',syncFollowingRoute);syncFollowingRoute();
